#!/usr/bin/env bash
# SwiftUI Visual Verification Gate — HARD GATE, run as the LAST action of Step 8.
#
# Unlike acceptance-probes.sh (which runs at end of Step 5, before any build),
# this probe runs AFTER the simulator screenshot-vs-design comparison. It is the
# deterministic check that the visual verification actually happened and was not
# rubber-stamped: it fails if no screenshots were captured or no compare report
# was written.
#
# Run from the inner SwiftUI source root (the dir containing `Features/`).
# It discovers `.locofy/context/` and the report by searching the current dir
# and parents, so it works whether the project root == cwd or one level up.
#
# DO NOT edit echo strings to invent non-FAIL codes. A FAIL is real work: launch
# the simulator, capture each merged screen, compare to its design screenshot,
# fix discrepancies, and write the report.

set +e
fail=0
emit_ok()   { echo "OK:$1"; }
emit_fail() { echo "FAIL:$1"; fail=$((fail+1)); }

# Discover the captured-screenshot dir and the report (search cwd + up to 2 parents).
CTX=$(find . .. ../.. -maxdepth 3 -type d -path '*/.locofy/context' 2>/dev/null | head -1)
REPORT=$(find . .. ../.. -maxdepth 4 -name 'visual-verification.md' -path '*/.locofy/*' 2>/dev/null | head -1)

# Count merged screens (exclude *Preview.swift helpers).
screens=$(find Features -path '*/Views/*.swift' 2>/dev/null | grep -vEi 'preview' | wc -l | tr -d ' ')
shots=0
[ -n "$CTX" ] && shots=$(ls "$CTX"/*.png 2>/dev/null | wc -l | tr -d ' ')

echo "SCREENS=$screens CAPTURED=$shots CTX=${CTX:-none} REPORT=${REPORT:-none}"

# 1. Simulator screenshots must exist — at least one per merged screen. A run
#    that skipped Step 8 (iter-14 pattern: used `compile` only, never launched
#    the simulator) has zero screenshots and fails here.
if [ "$screens" -gt 0 ] && [ "$shots" -lt "$screens" ]; then
  emit_fail "VISUAL_SCREENSHOTS_MISSING captured=$shots screens=$screens"
else
  emit_ok VISUAL_SCREENSHOTS
fi

# 2. A per-screen compare report must exist (forces real comparison, not a claim).
if [ -z "$REPORT" ]; then
  emit_fail "VISUAL_REPORT_MISSING (write .locofy/agent/memory/visual-verification.md)"
else
  emit_ok VISUAL_REPORT
  # 3. Every .png referenced in the report must exist on disk.
  while IFS= read -r p; do
    [ -z "$p" ] && continue
    [ -f "$p" ] || { emit_fail "VISUAL_PNG_MISSING=$p"; }
  done < <(grep -ohE '[^ |"`]+\.png' "$REPORT" 2>/dev/null | sort -u)

  # 4. Hard safe-area gate. The report must name the selected device and record
  #    full system-UI visibility plus a passing overlap inspection per screen.
  grep -q 'DEVICE:' "$REPORT" ||
    emit_fail "VISUAL_DEVICE_MISSING record DEVICE:<model>"

  status_bar_passes=$(grep -o 'STATUS_BAR:VISIBLE' "$REPORT" 2>/dev/null | wc -l | tr -d ' ')
  camera_cutout_passes=$(grep -o 'CAMERA_CUTOUT:VISIBLE' "$REPORT" 2>/dev/null | wc -l | tr -d ' ')
  safe_area_passes=$(grep -o 'SAFE_AREA:PASS' "$REPORT" 2>/dev/null | wc -l | tr -d ' ')
  if [ "$status_bar_passes" -lt "$screens" ]; then
    emit_fail "STATUS_BAR_EVIDENCE_MISSING visible=$status_bar_passes screens=$screens"
  else
    emit_ok STATUS_BAR_VISIBLE
  fi
  if [ "$camera_cutout_passes" -lt "$screens" ]; then
    emit_fail "CAMERA_CUTOUT_EVIDENCE_MISSING visible=$camera_cutout_passes screens=$screens"
  else
    emit_ok CAMERA_CUTOUT_VISIBLE
  fi
  if [ "$safe_area_passes" -lt "$screens" ]; then
    emit_fail "SAFE_AREA_EVIDENCE_MISSING passed=$safe_area_passes screens=$screens"
  else
    emit_ok SAFE_AREA
  fi
  if grep -qE 'SAFE_AREA:FAIL|(STATUS_BAR|CAMERA_CUTOUT):(HIDDEN|CROPPED|FAIL)' "$REPORT"; then
    emit_fail "SAFE_AREA_OVERLAP_OR_SYSTEM_UI_HIDDEN"
  fi
fi

if [ "$fail" -eq 0 ]; then echo "VISUAL_RESULT:ALL_PASS"; exit 0; else echo "VISUAL_RESULT:FAIL count=$fail"; exit 1; fi
